tools.example:
# Sweep a mode input without re-elaborating
foreach mode {0 1 2 3} {
  restart
  add_force /tb_top/mode $mode -radix unsigned
  run 50 us
  puts "mode $mode -> [get_value -radix hex /tb_top/result]"
}

# Finish and release the snapshot before starting another simulation
if {[current_sim] ne ""} { close_sim -force }
